/**
 * مكاتبُ الصور المتحرّكة — علميّةٌ ودراسيّة.
 * ------------------------------------------------------------------
 * خمسُ مكاتبَ كاملة: المدرسةُ وأدواتُها · العلوم · الفلكُ والفضاء ·
 * الرياضيات · الدراسةُ والتقدّم. تُتصفَّح مكتبةً مكتبة وتُدرج في الخطط
 * والكورسات كأيّ صورة.
 *
 * وكلُّ صورةٍ هنا **SVG متحرّكة** لا ملفَّ GIF. والفرقُ في مصلحة المنصّة:
 *   • وزنُها مئاتُ البايتات لا مئاتُ الكيلوبايتات — والصفحةُ تحمل مئةً
 *     منها بأقلَّ ممّا يزنه ملفُّ GIF واحد.
 *   • حوافُّها حادّةٌ في أيّ حجم — لا تتكسّر إن كُبّرت كما يقع للنقطيّة.
 *   • خلفيتُها شفّافةٌ أصلاً، فلا تحتاج قصّاً ولا مزجاً ولا حيلة.
 *   • لا تُجلَب من خادمٍ خارجي، فلا رخصةَ تُخرَق ولا رابطَ يموت.
 * وتُعرض في `<img>` كأيّ صورة، فحيثما قبِلت المنصّةُ صورةً قبِلت هذه.
 *
 * والحركةُ فيها SMIL داخل الملفّ نفسِه — تعمل داخل `<img>` حيث لا تعمل
 * أنماطُ CSS الخارجية.
 */

export type MotionLibId = "school" | "science" | "space" | "math" | "study" | "shari" | "arabic";

export const MOTION_LIBS: { id: MotionLibId; name: string }[] = [
  { id: "school", name: "المدرسة والأدوات" },
  { id: "science", name: "العلوم" },
  { id: "space", name: "الفلك والفضاء" },
  { id: "math", name: "الرياضيات" },
  { id: "study", name: "الدراسة والتقدّم" },
  { id: "shari", name: "العلوم الشرعية" },
  { id: "arabic", name: "العربية" },
];

export type MotionArt = {
  /** المكتبةُ التي ينتمي إليها. */
  lib: MotionLibId;
  id: string;
  /** اسمٌ عربيٌّ للبحث والعرض. */
  name: string;
  /** جسمُ الـSVG بلا وسمِ الجذر. */
  body: string;
};

function a(lib: MotionLibId, id: string, name: string, body: string): MotionArt {
  return { lib, id, name, body };
}

