/** ما في مكتبةٍ بعينها. */
export function libArt(lib: MotionLibId): MotionArt[] {
  return MOTION_ART.filter((x) => x.lib === lib);
}

/** الـSVG كاملاً — جذرٌ موحّدٌ لكلّ الصور فلا يتكرّر في كلّ مدخل. */
export function motionArtSvg(x: MotionArt): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64">${x.body}</svg>`;
}

/**
 * رابطُ بيانات صالحٌ لخاصية `src`.
 * التشفيرُ الكامل لا التجزئة: الوسمُ يحمل `#` و`<` و`&`، وتركُها خاماً
 * يكسر الرابط في بعض المتصفّحات.
 */
export function motionArtUrl(x: MotionArt): string {
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(motionArtSvg(x))}`;
}

export function findMotionArt(id?: string): MotionArt | undefined {
  return MOTION_ART.find((x) => x.id === id);
}
